class Solution {
  public String minWindow(String s, String t) {
    int[] need = new int[128];
    int[] have = new int[128];
    int required = 0;
    for (int i = 0; i < t.length(); i++) {
      if (need[t.charAt(i)] == 0) required++;
      need[t.charAt(i)]++;
    }
    int matched = 0, left = 0, start = 0, minLen = Integer.MAX_VALUE;
    for (int right = 0; right < s.length(); right++) {
      char c = s.charAt(right);
      have[c]++;
      if (need[c] > 0 && have[c] == need[c]) matched++;
      while (matched == required) {
        if (right - left + 1 < minLen) {
          minLen = right - left + 1;
          start = left;
        }
        char lc = s.charAt(left);
        if (need[lc] > 0 && have[lc] == need[lc]) matched--;
        have[lc]--;
        left++;
      }
    }
    return minLen == Integer.MAX_VALUE ? "" : s.substring(start, start + minLen);
  }
}

class Solution:
    def minWindow(self, s: str, t: str) -> str:
        from collections import Counter

        need = Counter(t)
        required = len(need)
        have = {}
        matched = 0
        left = 0
        start = 0
        min_len = float("inf")
        for right, c in enumerate(s):
            have[c] = have.get(c, 0) + 1
            if c in need and have[c] == need[c]:
                matched += 1
            while matched == required:
                if right - left + 1 < min_len:
                    min_len = right - left + 1
                    start = left
                lc = s[left]
                if lc in need and have[lc] == need[lc]:
                    matched -= 1
                have[lc] -= 1
                left += 1
        return "" if min_len == float("inf") else s[start:start + min_len]

impl Solution {
  pub fn min_window(s: String, t: String) -> String {
    let s = s.as_bytes();
    let mut need = [0i32; 128];
    let mut have = [0i32; 128];
    let mut required = 0;
    for &c in t.as_bytes() {
      if need[c as usize] == 0 {
        required += 1;
      }
      need[c as usize] += 1;
    }
    let (mut matched, mut left, mut start, mut min_len) = (0, 0usize, 0usize, usize::MAX);
    for right in 0..s.len() {
      let c = s[right] as usize;
      have[c] += 1;
      if need[c] > 0 && have[c] == need[c] {
        matched += 1;
      }
      while matched == required {
        if right - left + 1 < min_len {
          min_len = right - left + 1;
          start = left;
        }
        let lc = s[left] as usize;
        if need[lc] > 0 && have[lc] == need[lc] {
          matched -= 1;
        }
        have[lc] -= 1;
        left += 1;
      }
    }
    if min_len == usize::MAX {
      String::new()
    } else {
      String::from_utf8(s[start..start + min_len].to_vec()).unwrap()
    }
  }
}

const minWindow = (s: string, t: string): string => {
  const need: number[] = new Array(128).fill(0);
  const have: number[] = new Array(128).fill(0);
  let required = 0;
  for (const ch of t) {
    const c = ch.charCodeAt(0);
    if (need[c] === 0) required++;
    need[c]++;
  }
  let matched = 0;
  let left = 0;
  let start = 0;
  let minLen = Infinity;
  for (let right = 0; right < s.length; right++) {
    const c = s.charCodeAt(right);
    have[c]++;
    if (need[c] > 0 && have[c] === need[c]) matched++;
    while (matched === required) {
      if (right - left + 1 < minLen) {
        minLen = right - left + 1;
        start = left;
      }
      const lc = s.charCodeAt(left);
      if (need[lc] > 0 && have[lc] === need[lc]) matched--;
      have[lc]--;
      left++;
    }
  }
  return minLen === Infinity ? '' : s.slice(start, start + minLen);
};
